(function () {
	"use strict";

	// Register the plugin for TinyMCE 8
	tinymce.PluginManager.add("toc", function (editor) {
		// Helpers to read params (with defaults)
		var getTocClass = function () {
			return editor.getParam("toc_class", "mce-toc");
		};

		var getTocHeader = function () {
			var h = editor.getParam("toc_header", "h2");
			return /^h[1-6]$/.test(h) ? h : "h2";
		};

		var getTocDepth = function () {
			var depth = parseInt(editor.getParam("toc_depth", "3"), 10);
			return 1 <= depth && depth <= 9 ? depth : 3;
		};

		// id generator (similar to original code)
		var _prefix = "mcetoc_";
		var _counter = 0;
		var uniqueId = function () {
			var t = new Date().getTime().toString(32);
			return _prefix + t + (_counter++).toString(32);
		};

		// find headers and build items (like original v function)
		var collectHeaders = function () {
			var tocClass = getTocClass();
			var headerTag = getTocHeader();
			var depth = getTocDepth();

			// build selector like "h1,h2,h3"
			var selectors = [];
			for (var i = 1; i <= depth; i++) selectors.push("h" + i);
			var selector = selectors.join(",");

			// select within the editor body
			var root = editor.getBody();
			var nodes = editor.dom.select(selector, root) || [];

			// filter out headers that are inside existing TOC containers
			nodes = nodes.filter(function (el) {
				// if header tag doesn't match headerTag pattern, keep as before
				// original code filtered out headers whose parent had the toc class
				// here we check if any ancestor has the toc class
				return !editor.dom.getParent(el, "." + tocClass);
			});

			// map to items with id/level/title/element
			return nodes.map(function (el) {
				var id = el.id ? el.id : uniqueId();
				return {
					id: id,
					level: parseInt(el.nodeName.replace(/^H/i, ""), 10),
					title: editor.dom.getOuterText ? editor.dom.getOuterText(el) : el.textContent || "",
					element: el
				};
			});
		};

		// Build TOC HTML string like original d function
		var buildTocHtml = function () {
			var items = collectHeaders();
			if (!items.length) return "";

			// find minimum level (u in original) but subtract 1 to manage nesting loop logic
			var minLevel = 9;
			for (var j = 0; j < items.length; j++) {
				if (items[j].level < minLevel) minLevel = items[j].level;
				if (minLevel === 1) break;
			}
			var currentBase = minLevel - 1;

			var html = "";
			// header wrapper (e.g., <h2>Table of Contents</h2>)
			var headerTag = getTocHeader();
			var title = editor.translate ? editor.translate("Table of Contents") : "Table of Contents";
			html += "<" + headerTag + ' contenteditable="true">' + editor.dom.encode(title) + "</" + headerTag + ">";

			for (var k = 0; k < items.length; k++) {
				var it = items[k];
				// ensure element has id
				it.element.id = it.id;

				var nextLevel = items[k + 1] && items[k + 1].level;

				if (currentBase === it.level) {
					html += "<li>";
				} else {
					for (var n = currentBase; n < it.level; n++) {
						html += "<ul><li>";
					}
				}

				html += '<a href="#' + it.id + '">' + editor.dom.encode(it.title) + "</a>";

				if (nextLevel !== it.level && nextLevel) {
					for (var m = it.level; nextLevel < m; m--) {
						html += "</li></ul><li>";
					}
				} else {
					html += "</li>";
					if (!nextLevel) {
						html += "</ul>";
					}
				}

				currentBase = it.level;
			}

			return html;
		};

		// update existing TOC contents: find .tocClass and replace inner HTML
		var updateToc = function () {
			var tocClass = getTocClass();
			var nodes = editor.dom.select("." + tocClass, editor.getBody()) || [];
			if (!nodes.length) return;

			// If selection is inside an offscreen-selection (rare), insert new instead:
			// But we replicate original logic: if first found element is inside .mce-offscreen-selection -> insert new
			var first = nodes[0];
			var parents = editor.dom.getParents(first, ".mce-offscreen-selection");
			if (parents && parents.length) {
				insertToc(); // fallback
				return;
			}

			editor.undoManager.transact(function () {
				for (var i = 0; i < nodes.length; i++) {
					// set contenteditable attributes like original update
					nodes[i].innerHTML = buildTocHtml();
				}
			});
		};

		// insert a new TOC (<div class="mce-toc" contenteditable="false">...toc html...</div>)
		var insertToc = function () {
			var tocClass = getTocClass();
			var existing = editor.dom.select("." + tocClass, editor.getBody()) || [];

			// replicate original decision: if no existing or inside offscreen selection -> insert new, else update existing
			if (!existing.length || (editor.dom.getParents && editor.dom.getParents(existing[0], ".mce-offscreen-selection") || []).length) {
				var html = '<div class="' + editor.dom.encode(tocClass) + '" contenteditable="false">' + buildTocHtml() + "</div>";
				editor.insertContent(html);
			} else {
				// otherwise update existing
				updateToc();
			}
		};

		// hasHeaders check
		var hasHeaders = function () {
			return collectHeaders().length > 0;
		};

		// Commands
		editor.addCommand("mceInsertToc", function () {
			insertToc();
		});

		editor.addCommand("mceUpdateToc", function () {
			updateToc();
		});

		// Keep contenteditable attributes in sync (original "h" function)
		// PreProcess: remove contentEditable attributes from TOC when content is serialized
		editor.on("PreProcess", function (e) {
			var tocClass = getTocClass();
			var nodes = editor.dom.select("." + tocClass, e.node) || [];
			if (nodes.length) {
				for (var i = 0; i < nodes.length; i++) {
					nodes[i].removeAttribute("contenteditable");
					// remove inner contenteditable too
					var children = nodes[i].querySelectorAll("[contenteditable]");
					for (var j = 0; j < children.length; j++) children[j].removeAttribute("contenteditable");
				}
			}
		});

		// When content is set into the editor, mark TOC container contenteditable=false and its first child editable (like original)
		editor.on("SetContent", function () {
			var tocClass = getTocClass();
			var nodes = editor.dom.select("." + tocClass, editor.getBody()) || [];
			for (var i = 0; i < nodes.length; i++) {
				nodes[i].setAttribute("contenteditable", "false");
				if (nodes[i].firstElementChild) {
					nodes[i].firstElementChild.setAttribute("contenteditable", "true");
				}
			}
		});

		// UI: Buttons, menu items, context toolbar
		// Helper to keep buttons disabled when no headers / readonly
		var makeOnSetup = function () {
			return function (api) {
				var update = function () {
					api.setEnabled(!editor.mode.isReadOnly() && hasHeaders());
				};

				// update on content changes and editor state changes
				editor.on("LoadContent SetContent change", update);
				update();
			};
		};

		// Add toolbar button "toc"
		editor.ui.registry.addButton("toc", {
			tooltip: "Table of Contents",
			icon: "toc",
			onAction: function () {
				editor.execCommand("mceInsertToc");
			},
			onSetup: makeOnSetup()
		});

		// Add toolbar button "tocupdate"
		editor.ui.registry.addButton("tocupdate", {
			tooltip: "Update",
			icon: "reload",
			onAction: function () {
				editor.execCommand("mceUpdateToc");
			}
		});

		// add menu item under Insert context
		editor.ui.registry.addMenuItem("toc", {
			text: "Table of Contents",
			context: "insert",
			onAction: function () {
				editor.execCommand("mceInsertToc");
			},
			onSetup: makeOnSetup()
		});

		// Add a context toolbar similar to old addContextToolbar
		// TinyMCE 8 expects a name and options object with predicate and items
		editor.ui.registry.addContextToolbar("toc", {
			predicate: function (node) {
				// show when node is inside a TOC container
				if (!node) return false;
				return editor.dom.is(node, "." + getTocClass()) && editor.getBody().contains(node);
			},
			items: "tocupdate",
			position: "node",
			scope: "editor"
		});

		// Provide plugin metadata (optional)
		return {
			getMetadata: function () {
				return {
					name: "Table of Contents",
				};
			}
		};
	});
})();
